#!/usr/bin/env bash
# C0D1X VPN — self-contained Ubuntu/Debian installer + console.
# C0D1X VPN console manager (managed)
# shellcheck disable=SC2317
# Unreachable payload and cleanup called by trap are intentional.
# Inspect first: bash vpn-install.sh --extract ./sources
set -Eeuo pipefail
umask 077
VERSION='0.9.2'
INSTALL_DIR='/opt/vpn'
PROJECT_NAME='vpn'
BACKUP_DIR='/var/backups/vpn'
MANAGER_PATH='/usr/local/sbin/vpn'
MANAGER_MARKER='# C0D1X VPN console manager (managed)'
REPO_RAW_URL='https://raw.githubusercontent.com/justac0d1x/C0D1X-VPN-installer/refs/heads/main/main.sh'
# Existing certificates (3x-ui/certbot/acme.sh) are offered for HTTPS reuse.
TLS_CRON_PATH='/etc/cron.d/vpn-tls'
STRAY_CRON_PATH='/etc/cron.d/vpn-strays'
TLS_SCAN_ROOTS=(/etc/letsencrypt/live "${HOME:-/root}/.acme.sh" /root/.acme.sh /root/cert /root/certs)
PAYLOAD_SHA256='a02d054f26631ee09df3eaf26a24a71c15747251b8e95cd844518801d3d51538'
SELF="$(readlink -f -- "${BASH_SOURCE[0]}")"
TMP=''
BUNDLED_COMPOSE=''
LAST_BACKUP=''
BACKUP_RUNNING=''
BACKUP_PARTIAL=''
BACKUP_NEEDS_RESTART=0
DOMAIN=''
HTTPS_PORT='443'
PORT_SET=0
YES=0
ACTION='auto'
EXTRACT=''
OS_ID=''
OS_CODENAME=''
TLS_MODE='acme'
TLS_CERT_HOST=''
TLS_KEY_HOST=''
TLS_SOURCE_DIR=''
TLS_CERT_CONTAINER=''
TLS_KEY_CONTAINER=''
FORCE_ACME=0

info() { printf '\n%s\n' "$*"; }
die() { printf '\nОшибка: %s\n' "$*" >&2; exit 1; }
cleanup() {
  if [[ "$BACKUP_NEEDS_RESTART" == 1 ]] && declare -F restore_running >/dev/null; then
    printf '\nВосстанавливаю ранее работающие контейнеры после прерванного бэкапа…\n' >&2
    restore_running "$BACKUP_RUNNING" || printf 'Не все контейнеры восстановлены. Используйте --status / --start.\n' >&2
  fi
  if [[ -n "$BACKUP_PARTIAL" && "$BACKUP_PARTIAL" == "$BACKUP_DIR"/vpn-*.partial ]]; then
    rm -f -- "$BACKUP_PARTIAL"
  fi
  if [[ -n "$TMP" && -d "$TMP" ]]; then rm -rf -- "$TMP"; fi
}
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM
trap 'printf "\nОшибка на строке %s. Операция не завершена; проверьте её статус. Готовые внешние бэкапы не удаляются.\n" "$LINENO" >&2' ERR

usage() {
  cat <<'HELP'
C0D1X VPN — бот, веб-управление, HTTPS и консоль обслуживания

  sudo bash vpn-install.sh          # новая установка / меню, если уже есть
  sudo bash vpn-install.sh --menu
  sudo vpn                         # команда появится после первого запуска
  sudo vpn --status
  sudo vpn --start
  sudo vpn --stop
  sudo vpn --restart
  sudo vpn --logs                   # последние логи приложения
  sudo vpn --logs-caddy
  sudo vpn --backup
  sudo vpn --update                 # загрузить свежий main.sh из репозитория и обновить (--local — пересобрать из этого .sh)
  sudo vpn --uninstall              # выбор режима; --yes НЕ обходит удаление
  sudo vpn --reset-password
  sudo vpn --setup-link
  sudo vpn --sync-tls               # перечитать внешний сертификат после его продления (вызывает cron)
  sudo vpn --kill-strays           # уничтожить все контейнеры-копии бота (кроме своей панели)
  sudo vpn --diagnose-bot          # выяснить, кто ещё опрашивает токен (контейнеры, БД, процессы)

  sudo bash vpn-install.sh --domain admin.example.com --yes
  sudo bash vpn-install.sh --domain admin.example.com --https-port 8443 --yes
  sudo bash vpn-install.sh --domain admin.example.com --acme   # всегда новый сертификат
  bash vpn-install.sh --extract ./vpn-sources

Ubuntu 22.04+ / Debian 12+, root, systemd. Если на сервере уже есть сертификат
(certbot, acme.sh как у 3x-ui, /root/cert), он предлагается к переиспользованию:
домен и HTTPS-порт подхватываются, новый ACME не выпускается, TCP 80 не нужен.
Иначе для нового HTTPS нужен домен на этот VPS, свободный TCP 80 и HTTPS-порт
(443 по умолчанию). Продлевает внешний сертификат его исходный сервис.
Токены и тарифы вводятся в браузере; .env генерируется автоматически.
Удаление БД/Engine — только интерактивно с точными фразами подтверждения.
Удаление Docker запрещено при чужих контейнерах (включая stopped), volumes/сетях.
Сам VPS/ОС и внешняя 3x-ui не удаляются. Общий containerd/runc не очищается.
Публичного сервера обновлений нет: новая версия кода требует нового .sh.
HELP
}

confirm() {
  if [[ "$YES" == 1 ]]; then return 0; fi
  [[ -t 0 ]] || { printf 'Для работы без терминала укажите --yes (кроме удаления).\n' >&2; return 1; }
  local answer
  read -r -p "$1 [y/N]: " answer || return 1
  case "$answer" in y|Y|yes|YES|д|Д|да|ДА) return 0;; *) return 1;; esac
}

valid_domain() {
  local label
  [[ ${#1} -le 253 && "$1" == *.* && "$1" != *..* && "$1" != .* && "$1" != *. && "$1" != *:*
     && "$1" =~ ^[a-z0-9.-]+$ ]] || return 1
  local -a labels
  IFS='.' read -r -a labels <<< "$1"
  for label in "${labels[@]}"; do
    [[ ${#label} -ge 1 && ${#label} -le 63 && "$label" =~ ^[a-z0-9]([a-z0-9-]*[a-z0-9])?$ ]] || return 1
  done
  [[ "${labels[-1]}" =~ [a-z] ]] || return 1
}

read_env() {
  # A dotenv file is DATA, never executable shell code.
  sed -n "s/^$1=//p" "$INSTALL_DIR/.env" | head -n 1
}

unpack() {
  command -v sha256sum >/dev/null || die 'Нужна sha256sum.'
  command -v base64 >/dev/null || die 'Нужна base64.'
  TMP="$(mktemp -d)"
  local line
  line="$(awk '/^__VPN_PAYLOAD__$/ {print NR+1;exit}' "$SELF")"
  [[ -n "$line" ]] || die 'В установщике отсутствует архив.'
  tail -n +"$line" "$SELF" | sed 's/^#//' | base64 --decode > "$TMP/source.tar.gz"
  printf '%s  %s\n' "$PAYLOAD_SHA256" "$TMP/source.tar.gz" | sha256sum --check --status || die 'Контрольная сумма архива не совпала.'
  tar -tzf "$TMP/source.tar.gz" > "$TMP/paths.txt"
  if grep -Eq '(^/|(^|/)\.\.(/|$))' "$TMP/paths.txt"; then die 'Небезопасные пути в архиве.'; fi
  mkdir "$TMP/source"
  tar --no-same-owner --no-same-permissions -xzf "$TMP/source.tar.gz" -C "$TMP/source"
  [[ -f "$TMP/source/compose.yaml" && -f "$TMP/source/app/web.py" && -f "$TMP/source/scripts/console.sh" ]] || die 'Архив неполон.'
  BUNDLED_COMPOSE="$TMP/source/compose.yaml"
}

port_busy() {
  if [[ -n "$(ss -H -ltn "( sport = :$1 )")" ]]; then return 0; fi
  if command -v docker >/dev/null; then
    local published
    published="$(docker_local ps --format '{{.Ports}}' 2>/dev/null || true)"
    [[ "$published" != *":$1->"* ]] || return 0
  fi
  return 1
}

install_docker() {
  if command -v docker >/dev/null; then
    docker_local compose version >/dev/null 2>&1 || die 'Docker есть, но нет docker compose. Установите подходящий Compose plugin, не удаляя существующий Docker.'
  else
    local package
    for package in docker.io docker-engine podman-docker containerd runc; do
      if dpkg-query -W -f='${Status}' "$package" 2>/dev/null | grep -q 'install ok installed'; then
        die "Найден $package. Автоматическая замена чужого container runtime запрещена. Подготовьте Docker + Compose plugin отдельно."
      fi
    done
    info 'Устанавливаю Docker из официального APT-репозитория…'
    apt-get update
    DEBIAN_FRONTEND=noninteractive apt-get install -y ca-certificates curl openssl
    local repo='/etc/apt/sources.list.d/vpn-docker.list'
    local -a apt_sources=(/etc/apt/sources.list /etc/apt/sources.list.d/*.list /etc/apt/sources.list.d/*.sources)
    if grep -Eq "^[[:space:]]*(deb[[:space:]]+.*|URIs:[[:space:]]+)https://download\\.docker\\.com/linux/$OS_ID([[:space:]/]|$)" "${apt_sources[@]}" 2>/dev/null; then
      info 'Существующий официальный Docker APT source сохранён (без дубликата Signed-By).'
    else
      [[ ! -e "$repo" && ! -L "$repo" && ! -e /etc/apt/keyrings/vpn-docker.asc && ! -L /etc/apt/keyrings/vpn-docker.asc ]] || die 'Имена APT source/key заняты. Сначала проверьте их вручную; чужие файлы не заменяются.'
      install -m 0755 -d /etc/apt/keyrings
      curl --proto '=https' --tlsv1.2 --fail --silent --show-error --retry 3 \
        "https://download.docker.com/linux/$OS_ID/gpg" -o /etc/apt/keyrings/vpn-docker.asc
      chmod 0644 /etc/apt/keyrings/vpn-docker.asc
      printf '# C0D1X VPN managed Docker repository\ndeb [arch=%s signed-by=/etc/apt/keyrings/vpn-docker.asc] https://download.docker.com/linux/%s %s stable\n' \
        "$(dpkg --print-architecture)" "$OS_ID" "$OS_CODENAME" > "$repo"
      chmod 0644 "$repo"
    fi
    apt-get update
    DEBIAN_FRONTEND=noninteractive apt-get install -y docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin
  fi
  if ! docker_local info >/dev/null 2>&1; then systemctl start docker || die 'Не удалось запустить локальный Docker.'; fi
  docker_local info >/dev/null 2>&1 || die 'Локальный Docker daemon недоступен.'
  docker_local compose version >/dev/null 2>&1 || die 'Требуется современный Compose plugin.'
}

check_platform() {
  [[ $EUID -eq 0 ]] || die 'Запустите через sudo.'
  [[ -r /etc/os-release ]] || die 'Не удалось определить ОС.'
  local our_version="$VERSION"
  # shellcheck source=/dev/null
  . /etc/os-release
  VERSION="$our_version"  # os-release перезаписывает VERSION («26.04 …») — восстановить
  OS_ID="${ID:-}"; OS_CODENAME="${VERSION_CODENAME:-}"
  case "$OS_ID" in
    ubuntu) [[ "${VERSION_ID%%.*}" =~ ^[0-9]+$ && "${VERSION_ID%%.*}" -ge 22 ]] || die 'Нужна Ubuntu 22.04+.';;
    debian) [[ "${VERSION_ID%%.*}" =~ ^[0-9]+$ && "${VERSION_ID%%.*}" -ge 12 ]] || die 'Нужна Debian 12+.';;
    *) die 'Поддерживаются Ubuntu и Debian, не производные дистрибутивы.';;
  esac
  [[ -n "$OS_CODENAME" ]] || die 'ОС не сообщает VERSION_CODENAME.'
  [[ -d /run/systemd/system ]] || die 'Нужен VPS с systemd, не контейнер.'
  command -v flock >/dev/null || die 'Нужна flock из util-linux.'
  [[ ! -L /run/vpn ]] || die 'Небезопасный каталог блокировки.'
  install -d -m 0700 /run/vpn
  if [[ "${VPNCTL_LOCK_HELD:-0}" != 1 ]]; then
    # Консоль, запустившая скачанный установщик, уже держит замок — пропускаем.
    exec 9>/run/vpn/console.lock
    if ! flock -n 9; then
      holders="$(fuser /run/vpn/console.lock 2>/dev/null | tr -s ' ')" || true
      if [[ -n "$holders" ]]; then
        die "Другая консоль/установка C0D1X VPN уже открыта (держит PID:$holders). Если это зависшая консоль прошлой сессии: sudo kill$holders — затем повторите."
      fi
      die 'Другая консоль/установка C0D1X VPN уже открыта. Завершите её перед новой операцией.'
    fi
    export VPNCTL_LOCK_HELD=1
  fi
}

container_is_known_bot_copy() {
  # Эвристики контейнера-копии: метка/образ/имя от нас или признак БД панели.
  local id="$1" project="$2" image="$3" name="$4"
  case "|$project|$image|$name|" in
    *vpn-control*|*'/vpn:'*|*' vpn/'*) return 0;;
  esac
  # Надёжная проверка: у нашего приложения внутри лежит /data/control.sqlite3.
  docker_local exec "$id" test -f /data/control.sqlite3 >/dev/null 2>&1
}

sweep_stray_bots() {
  # «Бот не останавливается» почти всегда значит: тот же токен опрашивает
  # забытый контейнер. Уничтожаем ВСЕ контейнеры, похожие на копию панели,
  # кроме контейнеров своего проекта ($PROJECT_NAME).
  command -v docker_local >/dev/null 2>&1 || return 0
  local rows row id name project image found=0
  rows="$(docker_local ps -a --format '{{.ID}}|{{.Names}}|{{.Label "com.docker.compose.project"}}|{{.Image}}' 2>/dev/null)" || return 0
  while IFS= read -r row; do
    IFS='|' read -r id name project image <<< "$row"
    [[ -n "$id" ]] || continue
    [[ "$project" == "$PROJECT_NAME" ]] && continue  # свою панель не трогаем
    container_is_known_bot_copy "$id" "$project" "$image" "$name" || continue
    docker_local rm -f -- "$id" >/dev/null 2>&1 || true
    info "Уничтожена копия контейнера с ботом: $name (проект '$project', образ $image)."
    found=1
  done <<< "$rows"
  [[ "$found" == 1 ]] && printf 'Копии уничтожены. Строка «Чужая копия» в панели погаснет сама в течение минуты.\n'
  [[ "$found" == 0 ]] && [[ "${1:-}" == verbose ]] && info 'Копий контейнеров с ботом не найдено. Если панель всё ещё пишет «Чужая копия» — выполните: sudo vpn --diagnose-bot'
  return 0
}

diagnose_bot() {
  # Почему «токен опрашивает другой процесс»: выводим всё, что помогает найти виновника.
  printf '\n=== Контейнеры Docker ===\n'
  docker_local ps -a --format 'table {{.Names}}\t{{.Label "com.docker.compose.project"}}\t{{.Image}}\t{{.Status}}' 2>/dev/null || true
  printf '\n=== Контейнеры с БД панели внутри (/data/control.sqlite3) ===\n'
  local rows row id name project image hit=0
  rows="$(docker_local ps --format '{{.ID}}|{{.Names}}|{{.Label "com.docker.compose.project"}}|{{.Image}}' 2>/dev/null)"
  while IFS= read -r row; do
    IFS='|' read -r id name project image <<< "$row"
    [[ -n "$id" ]] || continue
    if docker_local exec "$id" test -f /data/control.sqlite3 >/dev/null 2>&1; then
      if [[ "$project" == "$PROJECT_NAME" ]]; then
        printf '  %s (наш проект %s) — в порядке\n' "$name" "$project"
      else
        printf '  !!! %s (проект %s, образ %s) — КОПИЯ БОТА, будет уничтожена sweep\n' "$name" "${project:-нет}" "$image"
        hit=1
      fi
    fi
  done <<< "$rows"
  [[ "$hit" == 0 ]] || { printf '\nУничтожаю найденные копии…\n'; sweep_stray_bots; }
  printf '\n=== Каталоги установок/БД на хосте ===\n'
  find /opt /srv /home /root -maxdepth 3 -name control.sqlite3 -not -path "*/vpn/data/*" 2>/dev/null || true
  [[ ! -e /opt/vpn-control ]] || printf '  !!! найден каталог прежней установки /opt/vpn-control\n'
  printf '\n=== Процессы, говорящие с Telegram ===\n'
  command -v ss >/dev/null 2>&1 && ss -tnp 2>/dev/null | grep -i 'python\|telegram\|149.154\|91.108' || printf '  (ss не показал ничего подозрительного)\n'
  printf '\nЕсли копий нет, а предупреждение горит — токен опрашивается вне этого сервера: перевыпустите его у @BotFather (/revoke) и пропишите новый в Подключении.\n'
  return 0
}

deploy_application() {
  # Called as an ordinary command, NOT in if/! or another errexit-suppressed
  # context. All application management helpers additionally check failures.
  local existing="$1" old_domain old_port public_url bootstrap key manager_ok=0
  if [[ "$existing" == 1 ]]; then
    require_managed || die 'Повреждена установка.'
    compose_hash_guard || die 'Автоматическое обновление нестандартного Compose запрещено.'
    old_domain="$(read_env DOMAIN)"; old_port="$(read_env HTTPS_PORT)"
    [[ -z "$DOMAIN" || "$DOMAIN" == "$old_domain" ]] || die 'Обновление не меняет домен.'
    [[ "$PORT_SET" == 0 || "$HTTPS_PORT" == "$old_port" ]] || die 'Обновление не меняет порт.'
    DOMAIN="$old_domain"; HTTPS_PORT="$old_port"
    TLS_MODE="$(read_env TLS_MODE)"; [[ -n "$TLS_MODE" ]] || TLS_MODE='acme'
  else
    # Fresh install: prefer an already-issued certificate (3x-ui/certbot/acme.sh).
    if [[ "$FORCE_ACME" == 0 ]]; then
      if [[ -z "$DOMAIN" ]]; then
        if [[ -t 0 ]]; then tls_pick_certificate || true; fi
      else
        tls_use_matching_certificate || true
      fi
    fi
    if [[ -z "$DOMAIN" ]]; then
      [[ -t 0 ]] || die 'Нужен --domain admin.example.com'
      read -r -p 'Домен веб-панели, без https://: ' DOMAIN
      DOMAIN="${DOMAIN,,}"
    fi
  fi
  valid_domain "$DOMAIN" || die 'Некорректный домен: полное DNS-имя, без протокола/пути; IDN в punycode.'
  [[ "$HTTPS_PORT" =~ ^[1-9][0-9]{1,4}$ && "$HTTPS_PORT" -ge 1024 && "$HTTPS_PORT" -le 65535 || "$HTTPS_PORT" == 443 ]] || die 'HTTPS-порт: 443 либо 1024–65535.'
  info "C0D1X VPN: код из ЭТОГО файла $VERSION → $DOMAIN · $INSTALL_DIR"
  info 'Новая версия кода требует нового .sh. Docker base images будут обновлены; токены и БД сохраняются.'
  if [[ "$TLS_MODE" == external ]]; then
    info "Используется существующий сертификат: $TLS_CERT_HOST"
    info 'Новый ACME не выпускается и свободный TCP 80 не нужен; DNS и HTTPS-порт должны работать.'
  else
    info 'DNS A/AAAA должны указывать на VPS. TCP 80 и HTTPS-порт должны быть доступны извне.'
  fi
  confirm 'Разрешить зависимости и развёртывание?' || { info 'Отменено.'; return 1; }
  if ! command -v ss >/dev/null || ! command -v openssl >/dev/null || ! command -v curl >/dev/null; then
    apt-get update
    DEBIAN_FRONTEND=noninteractive apt-get install -y iproute2 openssl curl ca-certificates
  fi
  if [[ "$existing" == 0 ]]; then
    if [[ "$TLS_MODE" != external ]] && port_busy 80; then
      die 'TCP 80 занят. Чужой веб-сервер не остановлен. Используйте существующий сертификат (он подхватится автоматически), отдельный VPS или свой reverse proxy.'
    fi
    if port_busy "$HTTPS_PORT"; then
      if [[ "$PORT_SET" == 0 && "$HTTPS_PORT" == 443 ]] && ! port_busy 8443; then
        info '443 занят, возможно VPN. Можно оставить его и использовать 8443.'
        confirm 'Использовать 8443 для веб-панели?' || die 'Выберите порт через --https-port.'
        HTTPS_PORT=8443
      else die 'HTTPS-порт занят; ничего не остановлено.'; fi
    fi
  fi
  install_docker
  public_url="https://$DOMAIN"
  [[ "$HTTPS_PORT" == 443 ]] || public_url+=":$HTTPS_PORT"
  if [[ "$existing" == 1 ]]; then
    scope_guard || die 'Обновление запрещено: в Compose неожиданные сервисы.'
    console_backup yes
    bootstrap="$(read_env APP_BOOTSTRAP_TOKEN)"
    [[ "$(read_env APP_PUBLIC_URL)" == "$public_url" ]] || die 'DOMAIN/порт/APP_PUBLIC_URL в .env не согласованы. Сначала исправьте адрес.'
  else
    mkdir -p "$INSTALL_DIR"
    chmod 0750 "$INSTALL_DIR"
    key="$(openssl rand -base64 32 | tr '+/' '-_' | tr -d '\n')"
    bootstrap="$(openssl rand -hex 32)"
    printf 'DOMAIN=%s\nHTTPS_PORT=%s\nAPP_PUBLIC_URL=%s\nAPP_MASTER_KEY=%s\nAPP_BOOTSTRAP_TOKEN=%s\n' \
      "$DOMAIN" "$HTTPS_PORT" "$public_url" "$key" "$bootstrap" > "$INSTALL_DIR/.env"
    printf 'TLS_MODE=%s\n' "$TLS_MODE" >> "$INSTALL_DIR/.env"
    if [[ "$TLS_MODE" == external ]]; then
      printf 'TLS_CERT_HOST=%s\nTLS_KEY_HOST=%s\nTLS_SOURCE_DIR=%s\nTLS_CERT_CONTAINER=%s\nTLS_KEY_CONTAINER=%s\n' \
        "$TLS_CERT_HOST" "$TLS_KEY_HOST" "$TLS_SOURCE_DIR" "$TLS_CERT_CONTAINER" "$TLS_KEY_CONTAINER" >> "$INSTALL_DIR/.env"
    fi
    chmod 0600 "$INSTALL_DIR/.env"
    printf 'C0D1X VPN managed installation\n' > "$INSTALL_DIR/.vpn-managed"
  fi
  [[ "$bootstrap" =~ ^[A-Za-z0-9_-]{32,128}$ ]] || die 'Некорректный bootstrap token; восстановите .env из бэкапа.'
  cp -a -- "$TMP/source/." "$INSTALL_DIR/"
  mkdir -p "$INSTALL_DIR/data"
  chown 10001:10001 "$INSTALL_DIR/data"
  chmod 0700 "$INSTALL_DIR/data"
  sha256sum "$INSTALL_DIR/compose.yaml" | cut -d' ' -f1 > "$INSTALL_DIR/.compose-sha256"
  tls_apply_config || die 'Не удалось подготовить TLS-конфигурацию. Ничего не запущено.'
  if register_manager; then manager_ok=1; else info 'Команда vpn не установлена; скачанный .sh остаётся работоспособен.'; fi
  scope_guard || die 'Операция запрещена: конфликт ресурсов/нестандартный проект.'
  compose_local config --quiet
  info 'Обновляю Docker images и собираю приложение…'
  compose_local pull caddy
  compose_local build --pull app
  compose_local up -d --force-recreate --wait --wait-timeout 180
  printf '%s\n' "$VERSION" > "$INSTALL_DIR/.installed-version"
  sweep_stray_bots || true
  strays_install_cron || info 'Ловушка блуждающих копий не прописана в cron; доступна вручную: sudo vpn --kill-strays'

  if curl --fail --silent --output /dev/null --connect-timeout 5 --max-time 8 \
      --retry 12 --retry-delay 5 --retry-max-time 150 --retry-all-errors \
      --resolve "$DOMAIN:$HTTPS_PORT:127.0.0.1" "$public_url/healthz"; then
    info 'HTTPS готов (сертификат проверен).'
  else
    info 'Контейнеры запущены, но HTTPS не подтверждён. Проверьте DNS A/AAAA, firewall и логи Caddy.'
  fi
  if [[ "$existing" == 0 ]]; then
    printf '\nСоздайте владельца: %s/setup#%s\n' "$public_url" "$bootstrap"
    printf 'Далее: Подключение → Тарифы и подписки → Запустить бота.\n'
    if [[ "$TLS_MODE" == external ]]; then
      printf 'Сертификат не выписывался заново: использован существующий; продление осталось за его исходным сервисом.\n'
    fi
  else printf '\nВход: %s/login\n' "$public_url"; fi
  if [[ "$manager_ok" == 1 ]]; then printf '\nКонсоль: sudo vpn\n'; else printf '\nКонсоль: sudo bash %q --menu\n' "$SELF"; fi
  printf 'Бэкапы консоли: %s (содержат секреты). Сохраните их также вне VPS.\n' "$BACKUP_DIR"
}

set_action() {
  [[ "$ACTION" == auto || "$ACTION" == "$1" ]] || die 'Нельзя совмещать несколько действий в одной команде.'
  ACTION="$1"
}

main() {
  while [[ $# -gt 0 ]]; do
    case "$1" in
      --domain) [[ $# -ge 2 ]] || die 'После --domain нужен домен.'; DOMAIN="${2,,}"; shift 2;;
      --https-port) [[ $# -ge 2 ]] || die 'После --https-port нужен порт.'; HTTPS_PORT="$2"; PORT_SET=1; shift 2;;
      --acme) FORCE_ACME=1; shift;;
      --yes|-y) YES=1; shift;;
      --menu) set_action menu; shift;;
      --install) set_action install; shift;;
      --update) set_action update; shift;;
      --status) set_action status; shift;;
      --start) set_action start; shift;;
      --stop) set_action stop; shift;;
      --restart) set_action restart; shift;;
      --logs) set_action logs; shift;;
      --logs-caddy) set_action logs-caddy; shift;;
      --backup) set_action backup; shift;;
      --uninstall) set_action uninstall; shift;;
      --reset-password) set_action password; shift;;
      --setup-link) set_action setup-link; shift;;
      --local) VPNCTL_LOCAL=1; shift;;
      --sync-tls) set_action sync-tls; shift;;
      --kill-strays) set_action kill-strays; shift;;
      --diagnose-bot) set_action diagnose-bot; shift;;
      --extract) [[ $# -ge 2 && -n "$2" ]] || die 'После --extract нужен новый каталог.'; set_action extract; EXTRACT="$2"; shift 2;;
      --help|-h) usage; return 0;;
      *) die 'Неизвестный аргумент. См. --help.';;
    esac
  done
  unpack
  if [[ "$ACTION" == extract ]]; then
    [[ ! -e "$EXTRACT" && ! -L "$EXTRACT" ]] || die 'Каталог извлечения уже существует.'
    mkdir -p -- "$EXTRACT"
    cp -a -- "$TMP/source/." "$EXTRACT/"
    info "Исходники извлечены: $EXTRACT"
    return 0
  fi
  check_platform
  # shellcheck source=scripts/console.sh
  . "$TMP/source/scripts/console.sh"
  if [[ -e /opt/vpn-control || -L /opt/vpn-control || -x /usr/local/sbin/vpn-control ]]; then
    die 'Найдена прежняя установка под именем vpn-control. Сначала удалите её старой консолью: sudo vpn-control → пункт 10 (данных там нет — та же БД), затем повторите. Новое имя команды: vpn.'
  fi
  [[ ! -L "$INSTALL_DIR" ]] || die 'Каталог установки не должен быть symlink.'
  local existing=0 code old_yes
  if [[ -e "$INSTALL_DIR" ]]; then require_managed; existing=1; fi
  if [[ "$ACTION" == auto ]]; then
    if [[ "$existing" == 1 ]]; then ACTION=menu; else ACTION=install; fi
  fi
  case "$ACTION" in
    install) [[ "$existing" == 0 ]] || die 'Установка уже есть. Используйте --menu или --update.'; deploy_application 0;;
    update)
      [[ "$existing" == 1 ]] || die 'Установка не найдена.'
      if [[ "${VPNCTL_FROM_REPO:-0}" == 1 || "${VPNCTL_LOCAL:-0}" == 1 ]]; then
        deploy_application 1
      else
        update_from_repository --update || die 'Обновление из репозитория не удалось. Локальная пересборка: vpn --update --local'
      fi;;
    menu)
      [[ "$existing" == 1 ]] || die 'Сначала установите приложение без --menu.'
      if ! register_manager; then info 'Открываю меню из скачанного файла без замены чужой команды.'; fi
      while :; do
        code=0
        console_menu || code=$?
        case "$code" in
          0) return 0;;
          20)
            if confirm 'Загрузить свежий установщик из репозитория и обновить?'; then
              old_yes="$YES"; YES=1
              if [[ "${VPNCTL_FROM_REPO:-0}" == 1 || "${VPNCTL_LOCAL:-0}" == 1 ]]; then
                deploy_application 1
              elif ! update_from_repository --update --yes; then
                YES=0
                if confirm "Пересобрать из этого .sh (код $VERSION)?"; then
                  YES=1; deploy_application 1
                else info 'Обновление отменено.'; fi
              fi
              YES="$old_yes"
            else info 'Обновление отменено.'; fi
            ;;
          *) return "$code";;
        esac
      done
      ;;
    status) console_status;;
    start|stop|restart) console_service "$ACTION";;
    logs) console_logs app;;
    logs-caddy) console_logs caddy;;
    backup) console_backup yes;;
    password) console_password;;
    setup-link) console_setup_link;;
    sync-tls) console_sync_tls;;
    kill-strays) sweep_stray_bots verbose;;
    diagnose-bot) diagnose_bot;;
    uninstall)
      code=0
      console_uninstall_menu || code=$?
      [[ "$code" != 10 ]] || return 0
      return "$code"
      ;;
  esac
}

main "$@"
exit 0
